<?php
require __DIR__.'/config.php';require __DIR__.'/functions.php';requireLogin();if(user()['role']!=='customer')redirect('admin/index.php');$u=user();$st=db()->prepare('SELECT b.*,c.name car_name,c.image_url FROM bookings b JOIN cars c ON c.id=b.car_id WHERE b.customer_id=? ORDER BY b.created_at DESC');$st->execute([$u['id']]);$bookings=$st->fetchAll();$f=getFlash();pageTop('My Bookings');nav();?><main class="container"><div class="section-head"><div><p class="eyebrow">CUSTOMER PORTAL</p><h1>My booking history</h1><p class="muted">All your confirmed, completed and cancelled reservations.</p></div><a class="btn primary" href="index.php#fleet">Book another vehicle</a></div><?php if($f): ?><div class="flash <?=$f['type']?>"><?=e($f['message'])?></div><?php endif; ?><div class="table-wrap"><table><thead><tr><th>Booking</th><th>Vehicle</th><th>Route</th><th>Dates</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($bookings as $b): ?><tr><td><b><?=e($b['booking_code'])?></b><small><?=e($b['created_at'])?></small></td><td><?=e($b['car_name'])?></td><td><?=e($b['from_city'])?> → <?=e($b['to_city'])?><small><?=e($b['total_km'])?> km</small></td><td><?=e($b['pickup_date'])?><small>to <?=e($b['return_date'])?></small></td><td><?=money((float)$b['total_amount'])?></td><td><span class="status <?=$b['status']?>"><?=e(ucfirst($b['status']))?></span></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$bookings): ?><div class="empty">No bookings yet.</div><?php endif; ?></main><?php pageBottom(); ?>